package store

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
	"testing"
	"time"
)

func TestInviteToken(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	inv, err := s.CreateInvite(o.ID, "new@people.example", RoleMember, "usr_1", t0)
	if err != nil {
		t.Fatal(err)
	}
	if len(inv.Token) != 43 {
		t.Fatalf("token %q has %d characters, want 43", inv.Token, len(inv.Token))
	}
	raw, err := base64.RawURLEncoding.DecodeString(inv.Token)
	if err != nil || len(raw) != 32 {
		t.Fatalf("token %q is not 32 bytes of unpadded base64url: %v", inv.Token, err)
	}
	stored, ok := s.Invite(o.ID, inv.ID)
	if !ok {
		t.Fatal("the invite is not stored")
	}
	if stored.Token != "" || stored.TokenHash == "" || stored.TokenHash == inv.Token {
		t.Fatalf("the store kept more than the hash: %+v", stored)
	}
	if want := hashInviteToken(inv.Token); stored.TokenHash != want || len(want) != 64 {
		t.Fatalf("token hash = %q, want SHA-256 hex %q", stored.TokenHash, want)
	}
	if other, _ := s.CreateInvite(o.ID, "other@people.example", RoleViewer, "usr_1", t0); other.Token == inv.Token {
		t.Fatal("two invites got the same token")
	}

	b, err := json.Marshal(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), inv.Token) {
		t.Fatal("the snapshot state contains the token")
	}
	b, _ = json.Marshal(s.PendingInvites(o.ID, t0))
	if strings.Contains(string(b), inv.Token) {
		t.Fatal("the pending invites contain the token")
	}
}

func TestAcceptInvite(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	accept := func(token string, now time.Time) error {
		_, _, _, err := s.AcceptInvite(token, "New Person", now)
		return err
	}

	inv, _ := s.CreateInvite(o.ID, "new@people.example", RoleMember, "usr_1", t0)
	if err := accept("invite_nope", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown token: %v", err)
	}
	if err := accept("", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("empty token: %v", err)
	}
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if _, _, _, err := s2.AcceptInvite(inv.Token, "New Person", t0); err != nil {
		t.Fatalf("the token does not work after FromState: %v", err)
	}
	if err := accept(inv.Token, t0); !errors.Is(err, ErrInviteUsed) {
		t.Fatalf("a used token: %v", err)
	}

	// Seven days is still in time; a moment later it has expired.
	atLimit, _ := s.CreateInvite(o.ID, "limit@people.example", RoleMember, "usr_1", t0)
	if err := accept(atLimit.Token, t0.Add(InviteLifetime)); err != nil {
		t.Fatalf("an invite at seven days: %v", err)
	}
	late, _ := s.CreateInvite(o.ID, "late@people.example", RoleMember, "usr_1", t0)
	if err := accept(late.Token, t0.Add(InviteLifetime+time.Second)); !errors.Is(err, ErrInviteExpired) {
		t.Fatalf("an expired token: %v", err)
	}

	revoked, _ := s.CreateInvite(o.ID, "gone@people.example", RoleMember, "usr_1", t0)
	if _, err := s.RevokeInvite(o.ID, revoked.ID, t0); err != nil {
		t.Fatal(err)
	}
	if err := accept(revoked.Token, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("a revoked token: %v", err)
	}
}

func TestInviteAgainReplacesOlder(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	first, _ := s.CreateInvite(o.ID, "new@people.example", RoleMember, "usr_1", t0)
	second, err := s.CreateInvite(o.ID, "New@People.example", RoleViewer, "usr_1", t0.Add(time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	if got, _ := s.Invite(o.ID, first.ID); got.RevokedAt == nil {
		t.Fatal("the older invite was not revoked")
	}
	if _, _, _, err := s.AcceptInvite(first.Token, "New Person", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("the older token: %v", err)
	}
	if _, _, _, err := s.AcceptInvite(second.Token, "New Person", t0); err != nil {
		t.Fatalf("the newest token: %v", err)
	}
}

func TestPendingInvites(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	old, _ := s.CreateInvite(o.ID, "old@people.example", RoleMember, "usr_1", t0)
	fresh, _ := s.CreateInvite(o.ID, "fresh@people.example", RoleMember, "usr_1", t0.Add(6*24*time.Hour))
	now := t0.Add(8 * 24 * time.Hour)
	pending := s.PendingInvites(o.ID, now)
	if len(pending) != 1 || pending[0].ID != fresh.ID {
		t.Fatalf("pending at %v = %+v, want only %s (old %s expired)", now, pending, fresh.ID, old.ID)
	}
	if _, _, _, err := s.AcceptInvite(fresh.Token, "Fresh", now); err != nil {
		t.Fatal(err)
	}
	if got := s.PendingInvites(o.ID, now); len(got) != 0 {
		t.Fatalf("an accepted invite is pending: %+v", got)
	}
}

