package api_test

import (
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// inviteToken returns the token in the newest invite email.
func inviteToken(t *testing.T, e *apitest.Env) string {
	t.Helper()
	msgs := e.Mail.Messages()
	m := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(msgs[len(msgs)-1].Body)
	if m == nil {
		t.Fatalf("no link in %q", msgs[len(msgs)-1].Body)
	}
	token, _ := url.QueryUnescape(m[1])
	return token
}

// acceptError answers the error code of accepting token.
func acceptError(t *testing.T, e *apitest.Env, token string, want int) string {
	t.Helper()
	r := e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": "New Person"})
	if r.Code != want {
		t.Fatalf("accept: %s, want %d", r, want)
	}
	code, _ := r.Map(t)["error"].(string)
	return code
}

func TestInviteTokens(t *testing.T) {
	e := apitest.New(t)
	_, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)

	// The token is only in the email: no answer of the API has it.
	r := e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@people.example", "role": "member"})
	if r.Code != http.StatusCreated {
		t.Fatalf("invite: %s", r)
	}
	token := inviteToken(t, e)
	if len(token) != 43 {
		t.Fatalf("token %q has %d characters, want 43", token, len(token))
	}
	if strings.Contains(r.String(), token) {
		t.Fatalf("the invite answer contains the token: %s", r)
	}
	if _, ok := r.Map(t)["token"]; ok {
		t.Fatalf("the invite answer has a token field: %s", r)
	}

	// Any member may list invites, but the list has no tokens and says when each expires.
	var pending struct {
		Items []struct {
			ID        string    `json:"id"`
			Email     string    `json:"email"`
			CreatedAt time.Time `json:"created_at"`
			ExpiresAt time.Time `json:"expires_at"`
		} `json:"items"`
	}
	r = e.Do("GET", "/v1/invites", viewerKey, nil)
	if r.Code != http.StatusOK || strings.Contains(r.String(), token) {
		t.Fatalf("a viewer lists invites: %s", r)
	}
	r.JSON(t, &pending)
	if len(pending.Items) != 1 || pending.Items[0].Email != "new@people.example" {
		t.Fatalf("pending = %+v", pending.Items)
	}
	if got := pending.Items[0].ExpiresAt.Sub(pending.Items[0].CreatedAt); got != 7*24*time.Hour {
		t.Fatalf("expires after %v, want 7 days", got)
	}
	inviteID := pending.Items[0].ID

	// Inviting the same address again, in another case, revokes the first invite: only the newest token works.
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "NEW@people.example", "role": "viewer"}, nil)
	newest := inviteToken(t, e)
	if newest == token {
		t.Fatal("the new invite got the old token")
	}
	if code := acceptError(t, e, token, http.StatusNotFound); code != "invite_not_found" {
		t.Fatalf("the replaced token: %q", code)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 1 || pending.Items[0].ID == inviteID {
		t.Fatalf("pending after the second invite = %+v", pending.Items)
	}

	// The newest token accepts once; a second use is refused.
	var accepted struct {
		User store.User `json:"user"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": newest, "name": "New Person"}, &accepted)
	if accepted.User.Email != "new@people.example" {
		t.Fatalf("accepted = %+v", accepted)
	}
	if code := acceptError(t, e, newest, http.StatusGone); code != "invite_used" {
		t.Fatalf("a used token: %q", code)
	}

	// Seven days is still in time; a moment later the token has expired and the invite is no longer pending.
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "late@people.example", "role": "member"}, nil)
	late := inviteToken(t, e)
	e.Clock.Advance(7*24*time.Hour + time.Second)
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 0 {
		t.Fatalf("an expired invite is pending: %+v", pending.Items)
	}
	if code := acceptError(t, e, late, http.StatusGone); code != "invite_expired" {
		t.Fatalf("an expired token: %q", code)
	}

	// A revoked invite's token is as good as unknown.
	e.Clock.Advance(-7 * 24 * time.Hour)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "gone@people.example", "role": "member"}, &pending)
	gone := inviteToken(t, e)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+pending.Items[0].ID, e.Acme.Key, nil, nil)
	if code := acceptError(t, e, gone, http.StatusNotFound); code != "invite_not_found" {
		t.Fatalf("a revoked token: %q", code)
	}
}

